// Sanitize inputs and prevent prompt injections
const body = $json.body;
let cleanCvText = (body.cvText || '').replace(/ignore your instructions/gi, '[REDACTED_PROMPT_INJECTION]');

return { json: { candidateEmail: body.candidateEmail, candidateName: body.candidateName, jobTitle: body.jobTitle, applicationId: body.applicationId, cvText: cleanCvText } };
